package com.dronefleet.ui;
import com.dronefleet.security.*;import javax.swing.*;import java.awt.*;
public final class LoginFrame extends JFrame{private final AuthService auth;private final JTextField user=new JTextField("admin");private final JPasswordField pass=new JPasswordField("admin123");private final JLabel msg=new JLabel(" ");public LoginFrame(AuthService a){auth=a;setTitle("DroneFleet — Secure Login");setSize(420,260);setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);JPanel p=new JPanel(new GridBagLayout());GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(8,8,8,8);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;p.add(new JLabel("Username"),g);g.gridx=1;p.add(user,g);g.gridx=0;g.gridy=1;p.add(new JLabel("Password"),g);g.gridx=1;p.add(pass,g);JButton b=new JButton("Login");g.gridy=2;p.add(b,g);msg.setForeground(Color.RED);g.gridy=3;p.add(msg,g);g.gridy=4;p.add(new JLabel("Default: admin / admin123"),g);add(p);b.addActionListener(e->login());getRootPane().setDefaultButton(b);setVisible(true);}private void login(){auth.login(user.getText().trim(),new String(pass.getPassword())).ifPresentOrElse(s->{dispose();new MainFrame(s,auth);},()->msg.setText("Invalid username or password"));}}
